Run this Python script from the directory containing `data/sales_q3.csv`. It detects likely column names, filters Meridian Analytics’ won deals, and sums the contract values:

```bash
python - <<'PY'
import csv
from decimal import Decimal, InvalidOperation

path = "data/sales_q3.csv"

with open(path, newline="", encoding="utf-8-sig") as f:
    rows = list(csv.DictReader(f))

if not rows:
    raise SystemExit("The CSV contains no data rows.")

columns = list(rows[0])

def find_column(candidates):
    normalized = {
        c.lower().strip().replace("_", " ").replace("-", " "): c
        for c in columns
    }
    for candidate in candidates:
        if candidate in normalized:
            return normalized[candidate]
    raise SystemExit(
        f"Could not identify {candidates[0]!r} column. Available columns: {columns}"
    )

account_col = find_column([
    "account", "account name", "customer", "customer name",
    "company", "company name", "client"
])
status_col = find_column([
    "status", "deal status", "stage", "deal stage", "outcome"
])
value_col = find_column([
    "new contract value", "contract value", "deal value",
    "amount", "value", "arr", "acv"
])

def parse_money(value):
    cleaned = (
        str(value).strip()
        .replace("$", "")
        .replace(",", "")
        .replace("(", "-")
        .replace(")", "")
    )
    try:
        return Decimal(cleaned or "0")
    except InvalidOperation:
        raise SystemExit(f"Invalid value in {value_col!r}: {value!r}")

won_rows = [
    row for row in rows
    if row[account_col].strip().casefold() == "meridian analytics"
    and row[status_col].strip().casefold() in {"won", "closed won"}
]

total = sum((parse_money(row[value_col]) for row in won_rows), Decimal("0"))

print(f"Matched won deals: {len(won_rows)}")
print(f"Meridian Analytics total new contract value: ${total:,.2f}")
PY
```

This only counts rows whose customer name exactly matches “Meridian Analytics” (case-insensitive) and whose status is either “Won” or “Closed Won.”
